public boolean onTouchEvent(MotionEvent ev) {
    if (isTrackpadMultiFingerSwipe(ev)) {
        return false;
    }
    if (com.android.launcher3.hecker.HeckerWorkspaceGestures.touch(this, ev,
            !workspaceInModalState() && !isSwitchingState())) return true;
    return super.onTouchEvent(ev);
}
